// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;

    function setUp() public { c = new demo(); }

    // fuzzed params: from address (`fromAddr`), whether the callee should fail (`shouldFail`),
    // and a single recipient address and value via arrays encoded in one uint (we'll split)
    function testFuzz_property(address fromAddr, bool shouldFail, address toAddr, uint256 val) public {
        // keep _tos length exactly 1 to simplify observation (one external call)
        address[] memory tos = new address[](1);
        tos[0] = toAddr;
        uint[] memory vals = new uint[](1);
        vals[0] = val;

        // Deploy a recorder/controllable callee that exposes a function matching the selector
        // transferFrom(address,address,uint256)
        Recorder r = new Recorder();
        // configure whether it should revert when called
        r.setShouldFail(shouldFail);

        bool ok;
        // call and capture whether it reverted
        try c.transfer(fromAddr, address(r), tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assertion): The reference implementation always reverts when the callee fails,
        // so for any inputs, ok == !shouldFail. The mutant that drops require(_s) will allow ok == true even when shouldFail==true.
        assertTrue(ok == (!shouldFail));
    }
}

// Adversarial/observing helper contract. It declares the exact function signature that C calls
// so the ABI decoder is used. It can be toggled to revert to simulate failing external call.
contract Recorder {
    bool public shouldFail;
    // record last call arguments for potential inspection (not used in assert, but harmless)
    address public lastFrom;
    address public lastTo;
    uint256 public lastVal;

    function setShouldFail(bool f) external { shouldFail = f; }

    // This matches the selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        lastFrom = from;
        lastTo = to;
        lastVal = amount;
        if (shouldFail) revert("forced fail");
        return true;
    }
}
